refused_program.body:
git merge --no-edit {upstream_remote}/{upstream_branch} || true
conflicts=$(git -c core.quotePath=false diff --name-only --diff-filter=U -z | tr '\0' '\n')
if test -n "$conflicts"; then
  tmpd=$(mktemp -d)
  printf '%s\n' "$conflicts" | while IFS= read -r path; do
    test -n "$path" || continue
    git show ":1:$path" > "$tmpd/base" 2>/dev/null || : > "$tmpd/base"
    git show ":2:$path" > "$tmpd/local" 2>/dev/null || : > "$tmpd/local"
    git show ":3:$path" > "$tmpd/up" 2>/dev/null || : > "$tmpd/up"
    if test -s "$tmpd/up"; then
      awk -v base="$tmpd/base" -v local="$tmpd/local" -v up="$tmpd/up" 'BEGIN {
        nb = 0
        while ((getline line < base) > 0) {
          nb++
          B[nb] = line
        }
        close(base)
        nl = 0
        while ((getline line < local) > 0) {
          nl++
          L[nl] = line
        }
        close(local)
        nu = 0
        while ((getline line < up) > 0) {
          nu++
          U[nu] = line
        }
        close(up)
        for (i = 1; i <= nb; i++) {
          cnt[B[i]]++
        }
        for (i = 1; i <= nl; i++) {
          if (cnt[L[i]] > 0) {
            cnt[L[i]]--
            added[i] = 0
          } else {
            added[i] = 1
          }
        }
        for (i = 1; i <= nb; i++) {
          if (cnt[B[i]] > 0) {
            rem[B[i]] = cnt[B[i]]
            cnt[B[i]] = 0
          }
        }
        for (i = 1; i <= nl; i++) {
          if (added[i] != 1) continue
          p = L[i]
          sub(/[^ \t]+[ \t]*$/, "", p)
          if (p ~ /[^ \t]/) {
            for (j = 1; j <= nb; j++) {
              if (rem[B[j]] > 0) {
                q = B[j]
                sub(/[^ \t]+[ \t]*$/, "", q)
                if (q == p) {
                  rem[B[j]]--
                  added[i] = 2
                  break
                }
              }
            }
          }
        }
        for (i = 1; i <= nu; i++) {
          if (!(U[i] in upidx)) upidx[U[i]] = i
        }
        for (i = 1; i <= nl; i++) {
          if (added[i] != 1) continue
          a = 0
          for (j = i - 1; j >= 1; j--) {
            if (added[j] != 0) continue
            if (L[j] in upidx) {
              a = upidx[L[j]]
              break
            }
          }
          if (a > 0) {
            post[a] = post[a] L[i] "\n"
            continue
          }
          for (j = i + 1; j <= nl; j++) {
            if (added[j] != 0) continue
            if (L[j] in upidx) {
              a = upidx[L[j]]
              break
            }
          }
          if (a > 0) {
            pre[a] = pre[a] L[i] "\n"
            continue
          }
          tail = tail L[i] "\n"
        }
        for (i = 1; i <= nu; i++) {
          if (i in pre) printf "%s", pre[i]
          if (rem[U[i]] > 0) {
            rem[U[i]]--
          } else {
            printf "%s\n", U[i]
          }
          if (i in post) printf "%s", post[i]
        }
        printf "%s", tail
        exit
      }' < /dev/null > "$tmpd/out"
      cat "$tmpd/out" > "$path"
    fi
    git add -- "$path"
  done
  rm -rf "$tmpd"
fi
if test -f "$(git rev-parse --git-path MERGE_HEAD)"; then
  git commit --no-edit
fi
